local Players = game:GetService("Players")
local RS = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")
local CoreGui = game:GetService("CoreGui")
local UserInputService = game:GetService("UserInputService")
local LP = Players.LocalPlayer

local HUB = {
    dead = false,
    conns = {},
    drawings = {},
    highlights = {},
}

-- Character helpers used by the extracted system.
local function findChar()
    return LP.Character
end

local function findHum()
    local ch = LP.Character
    return ch and ch:FindFirstChildOfClass("Humanoid")
end

local function findHRP()
    local ch = LP.Character
    return ch and (
        ch:FindFirstChild("HumanoidRootPart")
        or ch.PrimaryPart
        or ch:FindFirstChildWhichIsA("BasePart")
    )
end

local GetCharacter = findChar
local GetHumanoid = findHum
local GetHRP = findHRP

local function GetRootCFrame()
    local hrp = findHRP()
    return hrp and hrp.CFrame
end

-- Instant 0-second egg prompt handling from the original steal system.
pcall(function()
    local pps = game:GetService("ProximityPromptService")
    table.insert(HUB.conns, pps.PromptButtonHoldBegan:Connect(function(prompt, player)
        if player == LP and tostring(prompt) == "CarryAreaEgg" then
            prompt.HoldDuration = 0
        end
    end))
end)

local function GetNetRemote(name) local net = RS:FindFirstChild("Packages") and RS.Packages:FindFirstChild("Networking") return net and net:FindFirstChild(name) end local function GetLocalSlot() if PlotState and PlotState.ResolveLocalSlot then local ok, slot = pcall(PlotState.ResolveLocalSlot) if ok and slot then return slot end end return 1 end local function GetLocalPlotCenter() local plotObj = PlotState and PlotState.ResolvePlot and PlotState.ResolvePlot() local pt = plotObj and plotObj.CenterPoint and (typeof(plotObj.CenterPoint) == "Vector3" and plotObj.CenterPoint or (plotObj.CenterPoint:IsA("BasePart") and plotObj.CenterPoint.Position)) if pt then return Vector3.new(pt.X, math.max(pt.Y, 70.4), pt.Z), CFrame.new(pt.X, math.max(pt.Y, 70.4), pt.Z) end return Vector3.new(464.7, 70.4, -364.0), CFrame.new(464.7, 70.4, -364.0) end -- ============================================================================== -- CLEAN ROAD & FLIGHT PATH NAVIGATION (Anti-Trap & Zero Kick Engine) -- ============================================================================== local MAIN_ROAD_Z = -364.5 local stealMovementMethod = "Tween Glide" -- "Tween Glide", "Fly Glide", "Safe Walk", "Anti Guard" local avoidTrapsEnabled = true local autoClaimMonsterChests = false local autoFeedMonster = false local function instantTP(cframe) local root = findHRP() if not root then return end root.CFrame = cframe root.AssemblyLinearVelocity = Vector3.zero root.AssemblyAngularVelocity = Vector3.zero task.spawn(function() local char = LP.Character if char then for _, part in ipairs(char:GetDescendants()) do if part:IsA("BasePart") then pcall(function() part.CanCollide = false end) end end end end) end local function heartbeatTP(cframeTarget, holdTime) local root = findHRP() if not root then return end local char = LP.Character if char then for _, part in ipairs(char:GetDescendants()) do if part:IsA("BasePart") then pcall(function() part.CanCollide = false end) end end end local conn conn = RunService.Heartbeat:Connect(function() local r = findHRP() if r and r.Parent then r.CFrame = cframeTarget r.AssemblyLinearVelocity = Vector3.zero r.AssemblyAngularVelocity = Vector3.zero end end) task.wait(holdTime or 0.25) if conn then conn:Disconnect() end local r2 = findHRP() if r2 then r2.CFrame = cframeTarget r2.AssemblyLinearVelocity = Vector3.zero r2.AssemblyAngularVelocity = Vector3.zero end end local BYPASS_FLOAT_HEIGHT = 6.7 local BYPASS_LEG_OFFSET = Vector3.new(0, -6.7, 0) local BYPASS_TP_OFFSET = Vector3.new(0, 6.7, 0) local function bypassReturnTP(safeCFrame, holdTime) local hrp = findHRP() if not hrp then return false end local targetPart = Workspace:FindFirstChild("SpawnLocation", true) if not targetPart or not targetPart:IsA("BasePart") then heartbeatTP(safeCFrame, holdTime or 0.3) return true end pcall(function() targetPart.CanCollide = false end) local char = LP.Character if char then for _, part in ipairs(char:GetDescendants()) do if part:IsA("BasePart") then pcall(function() part.CanCollide = false end) end end end local conn conn = RunService.Heartbeat:Connect(function() local r = findHRP() if not r or not r.Parent then return end pcall(function() targetPart.CFrame = r.CFrame * CFrame.new(BYPASS_LEG_OFFSET) end) r.CFrame = safeCFrame + BYPASS_TP_OFFSET r.AssemblyLinearVelocity = Vector3.zero r.AssemblyAngularVelocity = Vector3.zero pcall(function() targetPart.CFrame = safeCFrame end) end) task.wait(holdTime or 0.35) if conn then conn:Disconnect() end local r2 = findHRP() if r2 then r2.CFrame = safeCFrame r2.AssemblyLinearVelocity = Vector3.zero r2.AssemblyAngularVelocity = Vector3.zero end return true end local function restoreCollisions() local char = LP.Character if not char or not char.Parent then return end for _, part in ipairs(char:GetDescendants()) do if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then part.CanCollide = true end end end local function SafeTeleport(targetPos) local root = findHRP() if not root or not targetPos then return false end root.CFrame = CFrame.new(targetPos.X, math.max(targetPos.Y, 70.0), targetPos.Z) root.AssemblyLinearVelocity = Vector3.zero root.AssemblyAngularVelocity = Vector3.zero return true end local function NeutralizeTraps() local debris = Workspace:FindFirstChild("__DEBRIS") if not debris then return end for _, d in ipairs(debris:GetChildren()) do if d.Name == "PlayerTrap" and d:GetAttribute("Owner") ~= LP.Name then if d:IsA("BasePart") then d.CanTouch = false d.CanQuery = false end for _, c in ipairs(d:GetChildren()) do if c:IsA("BasePart") then c.CanTouch = false c.CanQuery = false if c.Name == "Hitbox" then c.CFrame = CFrame.new(0, -999, 0) end end end local tt = d:FindFirstChildWhichIsA("TouchTransmitter", true) if tt then pcall(function() tt:Destroy() end) end end end end local function MoveToPoint(target, speed, easeOut) local hrp = findHRP() if not hrp or not target then return false end local start = hrp.Position local dist = (target - start).Magnitude if dist < 1.0 then hrp.CFrame = CFrame.new(target.X, math.max(target.Y, 70.0), target.Z) hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero return true end speed = math.clamp(tonumber(speed) or tonumber(glideSpeed) or 750, 50, 750) local t0 = os.clock() local totalDist = dist while not HUB.dead do local dt = RunService.Heartbeat:Wait() local curPos = hrp.Position local toTarget = target - curPos local remain = toTarget.Magnitude if remain < 1.0 then break end local stepSpeed = speed if easeOut then local progress = 1 - math.clamp(remain / totalDist, 0, 1) stepSpeed = math.max(speed * (1 - progress * 0.8), 35) end local step = math.min(stepSpeed * dt, remain) local dir = toTarget.Unit local nextPos = curPos + dir * step hrp.CFrame = CFrame.lookAt(nextPos, nextPos + dir) hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero if os.clock() - t0 > (totalDist / 50 + 5) then break end end hrp.CFrame = CFrame.new(target.X, math.max(target.Y, 70.0), target.Z) hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero return true end local function FlyToPoint(target, speed, easeOut) local hrp = findHRP() if not hrp or not target then return false end local start = hrp.Position local dist = (target - start).Magnitude if dist < 1.0 then hrp.CFrame = CFrame.new(target.X, math.max(target.Y, 70.0), target.Z) hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero return true end speed = math.clamp(tonumber(speed) or tonumber(glideSpeed) or 750, 50, 750) local moveTime = math.max(dist / speed, 0.02) if easeOut then moveTime = moveTime * 1.25 end local t0 = os.clock() local delta = target - start local dir = delta.Magnitude > 0.001 and delta.Unit or Vector3.new(1, 0, 0) while os.clock() - t0 < moveTime and not HUB.dead do local dt = RunService.Heartbeat:Wait() local linearAlpha = math.clamp((os.clock() - t0) / moveTime, 0, 1) local a = linearAlpha if easeOut then a = math.sin(linearAlpha * (math.pi / 2)) end local cur = start:Lerp(target, a) hrp.CFrame = CFrame.lookAt(cur, cur + dir) local curSpeed = speed if easeOut then curSpeed = math.max(speed * (1 - linearAlpha * 0.8), 35) end hrp.AssemblyLinearVelocity = Vector3.new(dir.X * curSpeed, math.clamp(dir.Y * curSpeed, -15, 150), dir.Z * curSpeed) hrp.AssemblyAngularVelocity = Vector3.zero end hrp.CFrame = CFrame.new(target.X, math.max(target.Y, 70.0), target.Z) hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero return true end local SAFE_BOUNDARY_X = 580 -- right before entering the safe zone local SAFE_ZONE_SPEED = 245 -- 245 studs/s safe entry speed local function TravelRoadPath(targetPos, speed, isApproach) local hrp = findHRP() if not hrp or not targetPos then return false end if avoidTrapsEnabled then pcall(NeutralizeTraps) end local startPos = hrp.Position local safeY = math.max(startPos.Y, targetPos.Y, 70.4) local isReturningToBase = (targetPos.X < 560) if isReturningToBase and startPos.X > SAFE_BOUNDARY_X then -- 1. Sprint to main road at full speed (750 studs/s) local p1 = Vector3.new(startPos.X, safeY, MAIN_ROAD_Z) MoveToPoint(p1, speed, false) -- 2. Sprint along main road at full speed until 20 studs BEFORE safe zone local pSafeApproach = Vector3.new(SAFE_BOUNDARY_X, safeY, MAIN_ROAD_Z) MoveToPoint(pSafeApproach, speed, false) -- 3. Slow down to 245 studs/s before entering the safe zone local pBaseRoad = Vector3.new(targetPos.X, safeY, MAIN_ROAD_Z) MoveToPoint(pBaseRoad, SAFE_ZONE_SPEED, false) -- 4. Enter base pen at 245 studs/s local pPen = targetPos + Vector3.new(0, 1.2, 0) MoveToPoint(pPen, SAFE_ZONE_SPEED, isApproach == true) return true else local p1 = Vector3.new(startPos.X, safeY, MAIN_ROAD_Z) local p2 = Vector3.new(targetPos.X, safeY, MAIN_ROAD_Z) local p3 = targetPos + Vector3.new(0, 1.2, 0) MoveToPoint(p1, speed, false) MoveToPoint(p2, speed, false) MoveToPoint(p3, speed, isApproach == true) return true end end local function TravelFlyDirect(targetPos, speed, isApproach) local hrp = findHRP() if not hrp or not targetPos then return false end if avoidTrapsEnabled then pcall(NeutralizeTraps) end local startPos = hrp.Position local isReturningToBase = (targetPos.X < 560) local flyAltitude = math.max(startPos.Y, targetPos.Y, 70.4) + 28 if isReturningToBase and startPos.X > SAFE_BOUNDARY_X then -- Fly at full speed (750 studs/s) until right before safe zone local pSky1 = Vector3.new(startPos.X, flyAltitude, startPos.Z) local pSkySafe = Vector3.new(SAFE_BOUNDARY_X, flyAltitude, MAIN_ROAD_Z) FlyToPoint(pSky1, speed, false) FlyToPoint(pSkySafe, speed, false) -- Descend and slow down to 245 studs/s before entering safe zone local pGroundSafe = Vector3.new(SAFE_BOUNDARY_X, 70.4, MAIN_ROAD_Z) FlyToPoint(pGroundSafe, SAFE_ZONE_SPEED, false) local pBaseRoad = Vector3.new(targetPos.X, 70.4, MAIN_ROAD_Z) MoveToPoint(pBaseRoad, SAFE_ZONE_SPEED, false) local pPen = targetPos + Vector3.new(0, 1.2, 0) MoveToPoint(pPen, SAFE_ZONE_SPEED, isApproach == true) return true else local totalDist = (targetPos - startPos).Magnitude if totalDist < 25 then FlyToPoint(Vector3.new(targetPos.X, math.max(targetPos.Y, 70.0) + 1.2, targetPos.Z), speed, isApproach == true) return true end local pSky1 = Vector3.new(startPos.X, flyAltitude, startPos.Z) local pSky2 = Vector3.new(targetPos.X, flyAltitude, targetPos.Z) local pGround = Vector3.new(targetPos.X, math.max(targetPos.Y, 70.0) + 1.2, targetPos.Z) FlyToPoint(pSky1, speed, false) FlyToPoint(pSky2, speed, false) FlyToPoint(pGround, speed, isApproach == true) return true end end local function TravelSafeWalk(targetPos) local hum = findHum() local hrp = findHRP() if not hum or not hrp or not targetPos then return false end if avoidTrapsEnabled then pcall(NeutralizeTraps) end local startPos = hrp.Position local p1 = Vector3.new(startPos.X, startPos.Y, MAIN_ROAD_Z) local p2 = Vector3.new(targetPos.X, targetPos.Y, MAIN_ROAD_Z) local p3 = targetPos + Vector3.new(0, 1.2, 0) for _, pt in ipairs({ p1, p2, p3 }) do if HUB.dead then break end hum:MoveTo(pt) local t0 = os.clock() while (hrp.Position - pt).Magnitude > 4.5 and os.clock() - t0 < 5 and not HUB.dead do task.wait(0.05) end end return true end local function TravelToDestination(targetPos, speed, isApproach) if stealMovementMethod == "Fly Glide" then return TravelFlyDirect(targetPos, speed, isApproach) elseif stealMovementMethod == "Safe Walk" then return TravelSafeWalk(targetPos) else -- Both "Tween Glide" and "Anti Guard" smoothly glide to the egg via road return TravelRoadPath(targetPos, speed, isApproach) end end -- ============================================================================== -- RARITY & AREA DICTIONARIES (Dynamic scoring for Rare Egg Hunter) -- ============================================================================== local RARITY_SCORE_MAP = { ["Titan"] = 1100, ["Divine"] = 1000, ["Transcendent"] = 1000, ["Superior"] = 1000, ["Eternal"] = 900, ["Limited"] = 900, ["Secret"] = 800, ["Exotic"] = 800, ["Cosmic"] = 700, ["Exclusive"] = 700, ["Admin"] = 700, ["Mythic"] = 600, ["Mythical"] = 600, ["Prismatic"] = 600, ["Rainbow"] = 600, ["Squishy God"] = 600, ["BrainrotGod"] = 600, ["Legendary"] = 500, ["Epic"] = 400, ["Rare"] = 300, ["SuperRare"] = 200, ["Celestial"] = 200, ["Uncommon"] = 200, ["Basic"] = 100, ["Common"] = 100, } local AREA_COORDINATES = { ["Base / Plot"] = Vector3.new(491.7, 70.4, -364.4), ["Stands & Shops"] = Vector3.new(539.5, 68.0, -364.5), ["Forest"] = Vector3.new(596.0, 68.0, -328.0), ["Lake"] = Vector3.new(744.0, 68.5, -408.0), ["Desert"] = Vector3.new(948.0, 69.5, -323.0), ["Jungle"] = Vector3.new(1188.0, 68.5, -408.0), ["Snow"] = Vector3.new(1492.0, 69.0, -315.0), ["Volcano"] = Vector3.new(1882.0, 68.0, -398.0), ["Abyss Ocean"] = Vector3.new(2280.0, 68.0, -326.0), ["Prehistoric"] = Vector3.new(2812.0, 69.0, -398.0), ["Cosmic"] = Vector3.new(3390.0, 68.0, -324.0), ["Cherry Blossom"] = Vector3.new(4028.0, 68.5, -396.0), ["Titan Temple"] = Vector3.new(4796.0, 69.5, -328.0), ["Monster Event"] = Vector3.new(539.5, 68.0, -411.3), ["Dragon Event"] = Vector3.new(539.5, 68.0, -318.0), } local AREA_NAMES = { "Forest", "Lake", "Desert", "Jungle", "Snow", "Volcano", "Abyss Ocean", "Prehistoric", "Cosmic", "Cherry Blossom", "Titan Temple", "Monster Event", "Dragon Event" } local RARITY_NAMES = { "Titan", "Divine", "Superior", "Eternal", "Limited", "Secret", "Exotic", "Cosmic", "Exclusive", "Mythic", "Rainbow", "Squishy God", "Legendary", "Epic", "Rare", "Uncommon", "Common" } local MUTATION_FILTERS = { "Normal Only", "Mutated Only", "Parasite / Infested", "Rainbow Only", "Gold Only", "Silver Only", "Monstrous" } -- ============================================================================== -- AUTOMATION STATE & PERSISTENT RETURN POSITION -- ============================================================================== local autoStealEnabled = false local rareEggHunter = true local stealParasiteOnly = false local stealBigEggsOnly = false local selectedStealRarities = {} local selectedStealAreas = {} local selectedMutationTypes = {} local stealDelay = 1.5 local glideSpeed = 750 local ignoredEggs = {} -- [uid] = timestamp (prevents loops on failed eggs) -- Saved Return Position (automatically captured on first steal activation) local savedReturnCFrame = nil local instantPickupEnabled = true local noKnockbackEnabled = true local batAuraEnabled = false local batAuraRadius = 20 local batAuraDelay = 0.2 local antiRagdollEnabled = true -- ============================================================================== -- EGG STEALING, PLANTING & HATCHING CORE LOGIC (Strict Rarity Matching) -- ============================================================================== local function GetEggRarityInfo(egg) if not egg then return "Common", 100 end -- 1. Direct rarity property on egg if egg.Rarity then local r = egg.Rarity local name = type(r) == "table" and (r.DisplayName or r._id or r.Name) or tostring(r) local score = RARITY_SCORE_MAP[name] or (type(r) == "table" and tonumber(r.RarityNumber) and r.RarityNumber * 100) or 100 return name, score end -- 2. Individual Animal / Egg Rarity from Assets Catalog (AssetCategory) local cat = egg.AssetCategory or egg.Category or egg.Name if cat and AssetsData then local assetsDir = AssetsData.Directory or AssetsData local aInfo = assetsDir[cat] if aInfo and aInfo.Rarity then local r = aInfo.Rarity local name = type(r) == "table" and (r.DisplayName or r._id or r.Name) or tostring(r) local score = RARITY_SCORE_MAP[name] or (type(r) == "table" and tonumber(r.RarityNumber) and r.RarityNumber * 100) or 100 return name, score end end -- 3. Fallback to Area mapping if asset category wasn't found in catalog local areaData = AreasData and (AreasData.Directory or AreasData) and (AreasData.Directory or AreasData)[egg.AreaId] local rarity = areaData and areaData.Rarity local rarityId = (type(rarity) == "table" and (rarity._id or rarity.DisplayName or rarity.Name)) or (type(rarity) == "string" and rarity) or "Common" local raritiesTable = RarityData and (RarityData.Rarities or RarityData) or {} local rInfo = raritiesTable[rarityId] or {} local rarityDisplayName = (type(rInfo) == "table" and (rInfo.DisplayName or rInfo._id)) or (type(rarity) == "table" and rarity.DisplayName) or rarityId or "Common" local baseScore = RARITY_SCORE_MAP[rarityDisplayName] or RARITY_SCORE_MAP[rarityId] or (type(rarity) == "table" and tonumber(rarity.RarityNumber) and rarity.RarityNumber * 100) or 100 return rarityDisplayName, baseScore end local function isRarityAllowed(rarityName, filter) if not filter or type(filter) ~= "table" then return true end local count = 0 for _ in pairs(filter) do count = count + 1 end if count == 0 then return true end if filter[rarityName] == true then return true end local rLower = string.lower(tostring(rarityName)) for k, v in pairs(filter) do if type(v) == "string" and string.lower(v) == rLower then return true elseif type(k) == "string" and string.lower(k) == rLower and v == true then return true end end return false end local function isAreaAllowed(areaId, filter) if not filter or type(filter) ~= "table" then return true end local count = 0 for _ in pairs(filter) do count = count + 1 end if count == 0 then return true end if filter[areaId] == true then return true end local aLower = string.lower(tostring(areaId)) for k, v in pairs(filter) do if type(v) == "string" and string.lower(v) == aLower then return true elseif type(k) == "string" and string.lower(k) == aLower and v == true then return true end end return false end local function isMutationAllowed(muts, record, filter) local isParasite = (record and record.HasParasite == true) or (type(muts) == "table" and (table.find(muts, "Parasite") or table.find(muts, "Monstrous"))) or (record and (record.BaseMutation == "Parasite" or record.BaseMutation == "Monstrous")) if stealParasiteOnly and not isParasite then return false end if not filter or type(filter) ~= "table" then return true end local count = 0 for _ in pairs(filter) do count = count + 1 end if count == 0 then return true end local hasMut = type(muts) == "table" and #muts > 0 local allowed = false for _, opt in pairs(filter) do if type(opt) == "string" then if opt == "Normal Only" and not hasMut and not isParasite then allowed = true elseif opt == "Mutated Only" and (hasMut or isParasite) then allowed = true elseif (opt == "Parasite / Infested" or opt == "Monstrous") and isParasite then allowed = true elseif opt == "Silver Only" and type(muts) == "table" and table.find(muts, "Silver") then allowed = true elseif opt == "Gold Only" and type(muts) == "table" and (table.find(muts, "Gold") or table.find(muts, "Golden")) then allowed = true elseif opt == "Rainbow Only" and type(muts) == "table" and table.find(muts, "Rainbow") then allowed = true end end end return allowed end local function isBigEgg(record) if not record then return false end local scale = tonumber(record.AssetScale) or 1 local nestScale = tonumber(record.NestScale) or 1 return scale >= 1.35 or nestScale >= 1.0 end local function GetMatchingFieldEggs(areasFilter, raritiesFilter, mutationsFilter) if not EggState or not EggState.ReadFieldEggs then return {} end local ok, snapshot = pcall(EggState.ReadFieldEggs) if not ok or not snapshot or not snapshot.Records then return {} end local matched = {} for _, record in ipairs(snapshot.Records) do if record.State == "Slot" and record.BoundsCFrame then local isIgnored = ignoredEggs[record.Uid] and (os.clock() - ignoredEggs[record.Uid] < 2.5) if not isIgnored and (not stealBigEggsOnly or isBigEgg(record)) then local areaOk = isAreaAllowed(record.AreaId, areasFilter) local rarityName, baseScore = GetEggRarityInfo(record) local rarityOk = isRarityAllowed(rarityName, raritiesFilter) local muts = record.Mutations or {} local mutOk = isMutationAllowed(muts, record, mutationsFilter) -- Strict filter check: only insert if all selected filters match! if areaOk and rarityOk and mutOk then local mutBonus = 0 for _, m in ipairs(muts) do if m == "Rainbow" then mutBonus = mutBonus + 35 elseif m == "Gold" or m == "Golden" then mutBonus = mutBonus + 20 elseif m == "Silver" then mutBonus = mutBonus + 10 end end if record.HasParasite == true or (type(muts) == "table" and (table.find(muts, "Parasite") or table.find(muts, "Monstrous"))) then mutBonus = mutBonus + 800 end if isBigEgg(record) then mutBonus = mutBonus + 600 end table.insert(matched, { record = record, rarity = rarityName, score = baseScore + mutBonus }) end end end end -- Rare Egg Hunter: sort matched eggs by total score descending (Highest Rarity First) if #matched > 1 then table.sort(matched, function(a, b) return a.score > b.score end) end return matched end local function EnsureSavedReturnPosition() if not savedReturnCFrame then local hrp = findHRP() if hrp then savedReturnCFrame = hrp.CFrame end end end local function isPlayerCarryingEgg() local pg = LP:FindFirstChildOfClass("PlayerGui") local dropGui = pg and pg:FindFirstChild("DropHeldEgg") if dropGui and dropGui.Enabled == true then return true end local char = LP.Character if char then for _, t in ipairs(char:GetChildren()) do if t:IsA("Model") and (t.Name:lower():find("egg") or t:GetAttribute("Uid") or t:GetAttribute("AssetCategory")) then return true end if t:IsA("Tool") then if EggToolDisplay and EggToolDisplay.IsEggTool and EggToolDisplay.IsEggTool(t) then return true end if t:GetAttribute("IsEgg") == true or t:GetAttribute("Uid") ~= nil or t:GetAttribute("AssetCategory") ~= nil then return true end local tName = t.Name:lower() if tName:find("egg") or (tName ~= "bat" and tName ~= "defaulttool" and not tName:find("bat") and not tName:find("slap") and not tName:find("coil") and not tName:find("potion") and not tName:find("lantern")) then return true end end end end local bp = LP:FindFirstChild("Backpack") if bp then for _, t in ipairs(bp:GetChildren()) do if t:IsA("Tool") and EggToolDisplay and EggToolDisplay.IsEggTool and EggToolDisplay.IsEggTool(t) then return true end end end return false end local function PlantAllCarriedEggsInPen() local plotObj = PlotState and PlotState.ResolvePlot and PlotState.ResolvePlot() local plotCenter = plotObj and plotObj.CenterPoint and plotObj.CenterPoint.Position or Vector3.new(464.7, 68.2, -364.0) local toolsToPlant = {} for _, t in ipairs(LP.Character:GetChildren()) do if t:IsA("Tool") and EggToolDisplay and EggToolDisplay.IsEggTool and EggToolDisplay.IsEggTool(t) then local uid = EggToolDisplay.GetToolUid(t) if uid then table.insert(toolsToPlant, uid) end end end for _, t in ipairs(LP.Backpack:GetChildren()) do if t:IsA("Tool") and EggToolDisplay and EggToolDisplay.IsEggTool and EggToolDisplay.IsEggTool(t) then local uid = EggToolDisplay.GetToolUid(t) if uid then table.insert(toolsToPlant, uid) end end end local plantedCount = 0 for _, eggUid in ipairs(toolsToPlant) do for attempt = 1, 3 do local offset = CFrame.new(math.random(-6, 6), 0, math.random(-6, 6)) local ok, res = pcall(function() if EggState and EggState.PlantEgg then return EggState.PlantEgg(eggUid, offset) end return false end) if ok and res then plantedCount = plantedCount + 1 break end task.wait(0.1) end end return plantedCount end local function StealSpecificEggRobust(targetItem) local record = targetItem.record or targetItem if not record or not record.Uid or not record.BoundsCFrame then return false end -- Verify the egg is still present in the latest snapshot before traveling if EggState and EggState.ReadFieldEggs then local ok, snap = pcall(EggState.ReadFieldEggs) if ok and snap and snap.Records then local stillThere = false for _, r in ipairs(snap.Records) do if r.Uid == record.Uid and r.State == "Slot" then stillThere = true record = r break end end if not stillThere then return false end end end local hrp = findHRP() local hum = findHum() if not hrp then return false end EnsureSavedReturnPosition() local targetPos = record.BoundsCFrame.Position local speed = math.clamp(tonumber(glideSpeed) or 