    isStealing = not isStealing
    if isStealing then
        ToggleBtn.BackgroundColor3 = Color3.fromRGB(50, 180, 50)
        ToggleBtn.Text = "AUTO STEAL: ON"
        StatusLabel.Text = "Status: Auto Stealing..."
        
        task.spawn(function()
            EnsureSavedReturnPosition()
