                local success = StealBestEggOnce()
                if success then
                    StatusLabel.Text = "Status: Stole best egg successfully!"
                else
                    StatusLabel.Text = "Status: Scanning or waiting for egg match..."
                end
                task.wait(1.5) -- หน่วงเวลาสแกนตามฟังก์ชันของระบบหลัก
            end
        end)
    else
        isStealing = false
        ToggleBtn.BackgroundColor3 = Color3.fromRGB(220, 50, 50)
        ToggleBtn.Text = "AUTO STEAL: OFF"
        StatusLabel.Text = "Status: Idle"
    end
end)
